<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import type { DesktopApi, ProjectSummary } from '../../../../contracts'
import type { MemberAssignment } from '../../../../contracts/group-chat/group-chat'
import { useGroupChat } from '../composables/use-group-chat'
import AssistantChatSurface from '../../assistant/components/AssistantChatSurface.vue'
import AssistantDocument from '../../assistant/components/AssistantDocument.vue'
import AuthorQuestionCard from '../../assistant/components/AuthorQuestionCard.vue'
import ModelConnectionsSettings from '../../models/components/ModelConnectionsSettings.vue'
import ModelCreationDefaults from '../../models/components/ModelCreationDefaults.vue'
import GroupMemberSettings from './GroupMemberSettings.vue'
import StudioIcon from '../../../ui/StudioIcon.vue'
import '../assets/group-chat.css'
const props = defineProps<{ api: DesktopApi; visible: boolean; book: ProjectSummary | null; beforeCreate: () => Promise<boolean>; onCreated: (project: ProjectSummary) => Promise<void> }>()
const emit = defineEmits<{ openBook: [id: string]; setupModels: []; newBook: []; library: [] }>()
const chat = useGroupChat(props.api, () => props.visible, props.beforeCreate, props.onCreated, () => props.book)
const { sessions, session, loading, busy, error, draft, target, turns, running, waiting, scopeEpoch, restoreRevision, position, questionDraft, creationOpen, creationName, parent, preview, adoption } = chat
const memberSettings = ref<MemberAssignment | null>(null), leftOpen = ref(false), resultsOpen = ref(false), composing = ref(false)
const modelManagerOpen = ref(false), modelManagerDirty = ref(false), modelManagerDialog = ref<HTMLDialogElement>()
const hidden = ref(document.hidden), visibility = () => { hidden.value = document.hidden }
onMounted(() => document.addEventListener('visibilitychange', visibility))
onBeforeUnmount(() => document.removeEventListener('visibilitychange', visibility))
watch(modelManagerOpen, async value => { await nextTick(); if (value) modelManagerDialog.value?.showModal(); else modelManagerDialog.value?.close() })
function closeModels() { if (modelManagerDirty.value) return; modelManagerOpen.value = false }
const settingsDialog = ref<HTMLDialogElement>(), creationDialog = ref<HTMLDialogElement>(), adoptionDialog = ref<HTMLDialogElement>(), composer = ref<HTMLTextAreaElement>()
const members = computed(() => session.value?.team.members ?? [])
const member = (id?: string) => members.value.find(member => member.id === id)
const memberColor = (color?: string) => color && ['jade', 'blue', 'rose', 'amber', 'violet', 'orange', 'slate'].includes(color) ? color : 'slate'
function openMemberSettings(id: string) { if (!session.value || session.value.readOnly || busy.value) return; const assignment = session.value.members.find(member => member.memberId === id); if (assignment) memberSettings.value = assignment; else error.value = '该成员已变化，请重新读取讨论。' }
const settingsTrigger = ref<HTMLElement>(), creationTrigger = ref<HTMLElement>(), adoptionTrigger = ref<HTMLElement>()
function saveTrigger(target: typeof settingsTrigger) { target.value = document.activeElement instanceof HTMLElement ? document.activeElement : undefined }
watch(memberSettings, async value => { if (value) { saveTrigger(settingsTrigger); await nextTick(); settingsDialog.value?.showModal() } else { settingsDialog.value?.close(); settingsTrigger.value?.focus() } })
watch(creationOpen, async value => { if (value) { saveTrigger(creationTrigger); await nextTick(); creationDialog.value?.showModal() } else { creationDialog.value?.close(); creationTrigger.value?.focus() } })
watch(adoption, async value => { if (value) { saveTrigger(adoptionTrigger); await nextTick(); adoptionDialog.value?.showModal() } else { adoptionDialog.value?.close(); adoptionTrigger.value?.focus() } })
watch(() => session.value?.id, () => { memberSettings.value = null; resultsOpen.value = false; leftOpen.value = false })
const assignedCount = computed(() => session.value?.members.filter(assignment => assignment.profile?.model).length ?? 0)
const idleStatus = computed(() => props.api.app.platform === 'browser' ? '等待讨论' : assignedCount.value === 0 ? '尚未分配模型' : `${assignedCount.value}/${members.value.length} 位已分配模型`)
const status = computed(() => session.value?.readOnly ? '历史只读' : ({ idle: idleStatus.value, running: '正在创作', 'waiting-input': '等待你的回答', 'waiting-creation': '等待建书', 'paused-limit': '待继续', interrupted: '执行中断', failed: '需要处理', cancelled: '已停止' }[session.value?.status ?? 'idle']))
async function send() { if (!composing.value) { await chat.send(); await nextTick(); composer.value?.focus() } }
function keydown(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key === 'Enter' && !event.isComposing && !composing.value && event.keyCode !== 229) { event.preventDefault(); void send() } }
async function startWith(text: string) { if (!session.value) await chat.create(); draft.value = text; await nextTick(); composer.value?.focus() }
async function saveMember(id: import('../../../../contracts/group-chat/group-chat').MemberId, profile: import('../../../../contracts/models/types').ModelProfile) { await chat.saveMember(id, profile); if (!error.value) memberSettings.value = null }
</script>
<template>
  <section class="group-workspace" :class="{ 'group-left-open': leftOpen, 'group-results-open': resultsOpen, 'motion-paused': hidden || !visible }" aria-label="小说创作群聊" data-testid="group-chat-workspace">
    <div v-if="leftOpen || resultsOpen" class="group-mobile-backdrop" @click="leftOpen = false; resultsOpen = false" />
    <aside class="group-team-rail" aria-label="会话与创作团队">
      <header class="group-rail-title"><span class="group-wordmark">共创室</span><button type="button" title="新建作品" aria-label="新建作品" data-testid="new-group" :disabled="busy" @click="emit('newBook')"><StudioIcon name="plus" :size="17" /></button></header>
      <button class="group-new-session" data-testid="new-group-discussion" type="button" :disabled="busy || loading" @click="book ? chat.create() : emit('newBook')"><span>＋</span> {{ book ? '新建讨论' : '创建作品，开始共创' }}</button>
      <div class="group-session-list"><small class="group-eyebrow">本书会话</small><p v-if="!sessions.length" class="group-small-note">你的故事，从这里开始。</p><button v-for="s in sessions" :key="s.id" type="button" :class="{ selected: s.id === session?.id }" :disabled="busy" @click="chat.select(s.id)"><StudioIcon name="message" :size="16"/><span>{{ s.book?.title || s.title }}</span><i v-if="s.status === 'running'" class="group-running-dot" /></button></div>
      <div class="group-team-heading"><small class="group-eyebrow">小说创作团队</small><span>{{ members.length }} 位成员</span></div>
      <div class="group-member-list"><button v-for="m in members" :key="m.id" type="button" :class="{ working: session?.activeMember === m.id }" :disabled="!session || busy || session.readOnly" :aria-label="m.name + '成员设置'" @click="openMemberSettings(m.id)">
        <span class="group-avatar" :data-color="memberColor(m.color)">{{ m.initials }}</span><span class="group-member-info"><b>{{ m.name }}</b><small>{{ session?.members.find(a => a.memberId === m.id)?.profile?.model || '选择模型' }}</small></span><span class="group-member-more">⋯</span>
      </button></div>
      <footer class="group-team-footer"><span v-if="session">团队成员与职责已保存。</span><button v-if="api.app.platform !== 'browser'" type="button" @click="modelManagerOpen = true">模型接口 <span>↗</span></button><small v-else>使用站长开放的模型；用量计入账户。</small></footer>
    </aside>
    <div class="group-thread">
      <header class="group-thread-header"><button class="group-mobile-toggle" type="button" aria-label="展开会话与成员" @click="leftOpen = !leftOpen"><StudioIcon name="menu" :size="20" /></button><div><h1>{{ session?.book?.title || book?.title || '小说共创室' }}</h1><span><i :class="{ 'group-running-dot': running }"/>{{ status }}<span class="group-header-team"> · {{ members.length }} 位成员</span></span></div><button v-if="session?.book" type="button" class="group-open-book" @click="emit('openBook', session.book.id)">进入作品 <span>↗</span></button><button class="group-results-toggle" type="button" aria-label="查看筹备成果" @click="resultsOpen = !resultsOpen"><StudioIcon name="outline" :size="18" /><span>成果</span><b>{{ session?.candidates.length || 0 }}</b></button></header>
      <p v-if="session?.readOnly" class="group-small-note" role="status">旧版讨论保留为只读历史。新建讨论可使用当前所选团队。</p>
      <AssistantChatSurface :turns="turns as import('../../assistant/services/assistant-presentation').AssistantTurn[]" :busy="Boolean(running)" :scope-epoch="scopeEpoch" :restore-revision="restoreRevision" :position="position" :visible="visible" :loading="loading" @position="chat.savePosition">
        <div class="group-message-column">
          <section v-if="!book" class="group-welcome group-book-empty" data-testid="group-book-empty">
            <p class="group-eyebrow">每本作品 · 一间共创室</p><h2>先给故事<br>取一个名字。</h2><p>创建时只需书名和类型。<br>采风、人物、世界与故事总纲，都可以在本书群聊里完成。</p>
            <div class="group-starting-prompts"><button type="button" @click="emit('newBook')"><span>创建作品</span><small>填写书名和类型，进入创作群 ↗</small></button><button type="button" @click="emit('library')"><span>选择已有作品</span><small>打开一本书，继续团队讨论 ↗</small></button></div>
          </section>
          <section v-else-if="!session?.messages.length && !session?.readOnly" class="group-welcome"><div class="group-orbit" aria-hidden="true"><span v-for="(m, index) in members.slice(0, 5)" :key="m.id" class="group-avatar" :data-color="memberColor(m.color)" :style="{ '--member-index': index }">{{ m.initials }}</span><span class="group-orbit-pen">✦</span></div><h2>与团队讨论这本书</h2><div class="group-starting-prompts"><button v-for="starter in session?.team.starters ?? []" :key="starter.id" type="button" :data-testid="`group-starter-${starter.id}`" @click="startWith(starter.message)"><span>{{ starter.label }}</span><small>{{ starter.hint }}</small></button></div></section>
          <p v-if="loading" class="group-small-note" role="status">正在读取会话…</p>
          <article v-for="message in session?.messages" :key="message.id" class="group-message" :class="message.role" :data-message-id="message.id">
            <template v-if="message.role === 'activity'"><span class="group-activity-mark">✓</span><span>{{ message.content }}</span><small>{{ member(message.memberId)?.name }}</small></template>
            <template v-else><span v-if="message.role === 'agent'" class="group-avatar" :data-color="memberColor(member(message.memberId)?.color)">{{ member(message.memberId)?.initials }}</span><div class="group-message-main"><header><b>{{ message.role === 'user' ? '你' : member(message.memberId)?.name }}</b><small v-if="message.model">{{ message.model }}</small><time>{{ new Date(message.createdAt).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }}</time></header><div class="group-message-content"><p v-if="message.role === 'user'">{{ message.content }}</p><AssistantDocument v-else :content="message.content" /></div></div></template>
          </article>
          <div v-if="running" class="group-typing" role="status"><span class="group-avatar" :data-color="memberColor(member(session?.activeMember ?? undefined)?.color)">{{ member(session?.activeMember ?? undefined)?.initials || '协' }}</span><span>{{ member(session?.activeMember ?? undefined)?.name || '团队' }}正在思考<span class="group-typing-dots"><i/><i/><i/></span></span></div>
          <AuthorQuestionCard v-if="session?.question" :question="session.question" :book-title="session.book?.title || session.title" :busy="busy || session.readOnly" :needs-resume="false" :run-id="session.id" :draft="questionDraft" @submit="chat.answer" @cancel="chat.stop" @defer="composer?.focus()" @update:draft="chat.saveQuestionDraft" />
          <section v-if="session?.creation && !session.readOnly" class="group-creation-card"><div class="group-creation-symbol">书</div><div><small>准备进入你的作品</small><h3>{{ session.creation.suggestedTitle }}</h3><p>{{ session.creation.summary }}</p><button type="button" class="control-button primary" :disabled="busy" @click="chat.openCreation">核对并创建作品 →</button></div></section>
          <section v-if="session && ['failed', 'interrupted', 'paused-limit'].includes(session.status)" class="group-attention" role="status"><p>{{ session.notice }}</p><button v-if="session.status !== 'failed'" type="button" :disabled="busy || session.readOnly" @click="chat.resume">核对后继续</button><button type="button" :disabled="busy || session?.readOnly" @click="chat.stop">停止原目标</button></section>
        </div>
        <template #composer><div class="group-composer-area"><p v-if="error" class="group-error" role="alert">{{ error }}<button type="button" @click="chat.load">重新读取</button></p><form class="group-composer" @submit.prevent="send" @keydown="keydown"><label class="group-visually-hidden" for="group-message-input">给创作团队的消息</label><textarea id="group-message-input" ref="composer" v-model="draft" :readonly="session?.readOnly" :disabled="loading || !book || !session" rows="2" maxlength="12000" :placeholder="waiting ? '请先处理上方等待，再继续讨论…' : '说说你的小说想法，或 @ 一位成员…'" @compositionstart="composing = true" @compositionend="composing = false"/><footer><label class="group-target"><span>发送给</span><select v-model="target" :disabled="session?.readOnly" aria-label="指定发言成员"><option value="">{{ members[0]?.name || "团队协调" }}</option><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }}</option></select></label><span class="group-shortcut">Ctrl / ⌘ + Enter</span><button v-if="running" type="button" class="group-stop" :disabled="busy || session?.readOnly" @click="chat.stop">■ 停止</button><button class="group-send" type="submit" :disabled="busy || loading || !book || !session || session.readOnly || !draft.trim() || Boolean(waiting) || composing" data-testid="group-send">{{ running ? '加入队列' : '发送' }} <span>↑</span></button></footer></form><p class="group-composer-note">{{ running ? `执行中 · ${session?.budget.steps} 步 · ${session?.budget.calls} 次工具调用` : '讨论与筹备成果会保存；正式内容由你核对采用。' }}</p></div></template>
      </AssistantChatSurface>
    </div>
    <aside class="group-results-rail" aria-label="筹备成果"><header><div><small class="group-eyebrow">故事工作台</small><h2>筹备成果</h2></div><span>{{ session?.candidates.length || 0 }}</span><button class="group-mobile-toggle" type="button" aria-label="关闭成果" @click="resultsOpen = false">×</button></header><div v-if="!session?.candidates.length" class="group-results-empty"><span>✧</span><h3>想法正在生长</h3><p>成员保存的世界、人物与故事<br>会收在这里，随时查看。</p><ol><li>聊清故事方向</li><li>整理世界与人物</li><li>核对并采用筹备成果</li><li>沿总纲逐层展开创作</li></ol></div><div v-else class="group-result-list"><details v-for="candidate in session.candidates" :key="candidate.id" class="group-result-card"><summary><small>{{ ({ definition: '作品定义', world: '世界观', characters: '人物', outline: '故事总纲', timeline: '事件筹备', research: '采风记录', adaptation: '情节改编' })[candidate.kind] }}</small><h3>{{ candidate.title }}</h3><span>{{ candidate.status === 'adopted' ? '已处理' : '待核对' }}</span></summary><AssistantDocument :content="candidate.content" /><ul v-if="candidate.references?.length" class="group-source-links" aria-label="灵感来源"><li v-for="source in candidate.references" :key="source.id"><a v-if="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title }} ↗</a><span v-else>{{ source.title }} · 本书参考资料</span></li></ul><button v-if="candidate.status === 'proposed'" type="button" :disabled="busy || running || session.readOnly || !session.book" @click="chat.prepareAdoption(candidate)">{{ !session.book ? '创建作品后可核对采用' : (candidate.domainDraft || ['world', 'definition'].includes(candidate.kind)) ? '核对并采用 →' : '核对并收为素材 →' }}</button></details></div><footer v-if="session?.book"><small>已关联作品</small><button type="button" @click="emit('openBook', session.book.id)">{{ session.book.title }} ↗</button></footer></aside>
    <dialog v-if="modelManagerOpen" ref="modelManagerDialog" class="group-dialog" aria-label="模型接口管理" @cancel.prevent="closeModels"><header><h2>模型接口与新书默认</h2><button type="button" aria-label="关闭模型接口管理" :disabled="modelManagerDirty" @click="closeModels">×</button></header><p v-if="modelManagerDirty">请先保存或放弃接口中的修改，再关闭。</p><ModelConnectionsSettings :api="api.modelConnections" :local-api="api.localModels" @dirty="modelManagerDirty = $event"/><footer><button type="button" class="control-button secondary" :disabled="modelManagerDirty" @click="closeModels">返回群聊</button></footer></dialog>
    <dialog v-if="memberSettings && session" ref="settingsDialog" class="group-dialog" @cancel.prevent="memberSettings = null"><GroupMemberSettings :key="memberSettings.memberId" :api="api" :member="memberSettings" :team="session.team" :busy="busy" @close="memberSettings = null" @save="saveMember" @setup="memberSettings = null; modelManagerOpen = true"/><p v-if="error" class="group-error" role="alert">{{ error }}</p></dialog>
    <dialog v-if="creationOpen" ref="creationDialog" class="group-dialog" aria-label="核对并创建作品" @cancel.prevent="creationOpen = false"><form @submit.prevent="chat.createBook"><header><h2>给故事一个家</h2><button type="button" aria-label="关闭建书" @click="creationOpen = false">×</button></header><p>群聊和筹备成果会保留，作品创建后继续在这里协作。</p><label>作品名<input v-model="creationName" maxlength="200" autofocus required /></label><label>保存位置<div class="group-directory"><input :value="parent" readonly required/><button type="button" @click="chat.chooseDirectory">{{ api.app.platform === 'browser' ? '账户书库' : '选择文件夹' }}</button></div></label><ModelCreationDefaults :api="api.modelConnections" :disabled="busy" @ready="preview = $event"/><p v-if="error" class="group-error" role="alert">{{ error }}</p><footer><button type="button" class="control-button secondary" :disabled="busy" @click="creationOpen = false">暂不创建</button><button type="submit" class="control-button primary" :disabled="busy || !preview || !parent || !creationName.trim()">{{ busy ? '正在建立…' : '创建并关联作品' }}</button></footer></form></dialog>
    <dialog v-if="adoption" ref="adoptionDialog" class="group-dialog group-adoption-dialog" aria-label="核对筹备采用" @cancel.prevent="adoption = null"><header><div><small>{{ adoption.bookTitle }} · {{ adoption.destination }}</small><h2>{{ adoption.title }}</h2></div><button type="button" aria-label="关闭采用预览" @click="adoption = null">×</button></header><p>{{ adoption.notice }}</p><div class="group-adoption-comparison"><section v-if="adoption.currentContent"><h3>现有内容</h3><AssistantDocument :content="adoption.currentContent" /></section><section><h3>待采用候选</h3><AssistantDocument :content="adoption.content" /></section></div><p v-if="error" class="group-error" role="alert">{{ error }}</p><footer><button type="button" class="control-button secondary" :disabled="busy" @click="adoption = null">保留候选</button><button type="button" class="control-button primary" :disabled="busy" @click="chat.adopt">确认采用到{{ adoption.destination }}</button></footer></dialog>
  </section>
</template>
